  "cegamento_participantes_equipe": {
    "julgamento": "High",
    "justificativa": "O cegamento dos anestesiologistas era impossível porque eles gerenciaram os pacientes de acordo com a alocação do grupo."
  },
  "cegamento_avaliadores_desfecho": {
    "julgamento": "Low",
    "justificativa": "Os investigadores que avaliaram os desfechos pós-operatórios e os cirurgiões estavam cegados à alocação dos grupos."
  },
  "dados_desfecho_incompletos": {
    "julgamento": "Low",
    "justificativa": "O estudo realizou uma análise por protocolo e uma análise de intenção de tratar como análise de sensibilidade, tratando as exclusões de pacientes por falta de dados ou violações de protocolo."
  },
  "relato_seletivo": {
    "julgamento": "Low",
    "justificativa": "O estudo reportou tanto o desfecho primário quanto os desfechos secundários conforme o protocolo e o registro no ClinicalTrials.gov."
  },
  "outros_vieses": {
    "julgamento": "Low",
    "justificativa": "O estudo foi registrado prospectivamente no ClinicalTrials.gov (NCT03505112) e seguiu os preceitos da Declaração de Helsinki."
  },
  "risco_global": {
    "julgamento": "High",
    "justificativa": "O risco global é alto devido à impossibilidade de cegar a equipe de anestesia que aplicou a intervenção."
